INSERT INTO policies (policy_id, title, category, body, effective_date, updated_at) VALUES
  (1, 'Return Policy', 'returns', 'Commerce Swarm accepts returns of non-perishable items within 30 calendar days of delivery for a full refund to the original payment method. Items must be unopened and in their original packaging. Frozen and perishable items are non-returnable for food-safety reasons but may be replaced or refunded if the customer reports a quality issue within 48 hours of delivery, supported by photographs. Custom orders, including custom-logo cakes, are non-returnable except in cases of manufacturing defects. To initiate a return, customers may use the self-service return portal in their account history or contact customer support. Refunds are issued within 5-7 business days of receipt of returned items.', DATE'2026-01-01', CURRENT_TIMESTAMP()),
  (2, 'Shipping Policy', 'shipping', 'Standard ground shipping within the continental United States is included free of charge on B2C orders over $75. Frozen and perishable orders ship via overnight or 2-day air using dry-ice insulated packaging at the customer''s expense. We ship Tuesday through Thursday to ensure transit avoids weekend warehouse delays for frozen items. B2B foodservice customers have scheduled weekly delivery windows defined in their service contract. Address changes after order placement may incur a re-routing fee. Commerce Swarm is not responsible for delays caused by extreme weather, carrier strikes, or destination-side receiving issues.', DATE'2026-01-01', CURRENT_TIMESTAMP()),
  (3, 'Privacy Policy', 'privacy', 'Commerce Swarm collects and processes customer data to fulfill orders, provide support, and personalize the shopping experience. Data collected includes name, contact information, shipping addresses, payment method (tokenized — we do not store full card numbers), order history, and interaction history with our customer service and recommendation systems. Personal data is never sold to third parties. We share data with shipping carriers and payment processors solely for order fulfillment. Customers may request data export or deletion via the privacy portal in their account. We comply with CCPA, GDPR (for EU residents), and other applicable privacy regulations. Cookie usage is governed by our cookie notice; preferences can be managed at any time.', DATE'2026-01-15', CURRENT_TIMESTAMP()),
  (4, 'B2B Terms of Service', 'b2b_terms', 'Approved B2B foodservice accounts operate under net-30 payment terms by default. Late payments accrue interest at 1.5% per month or the maximum permitted by applicable state law. Net-60 terms may be granted following demonstrated payment history and credit review. Commerce Swarm reserves the right to suspend net-payment privileges and require pre-payment for accounts with overdue balances exceeding 60 days. Minimum order quantities and delivery schedules are defined in each account''s service agreement. Pricing is reviewed annually and updated at the contract anniversary date with 30 days'' notice for any structural changes.', DATE'2026-01-01', CURRENT_TIMESTAMP()),
  (5, 'Credit Policy', 'payment', 'B2B credit limits are established at account opening based on tax-ID review, soft credit inquiry, and business size indicators. Initial limits typically range from $1,000 (small operators) to $50,000 (regional chains). Credit limits are reviewed quarterly; on-time payment history of 12+ months may trigger an automatic limit increase. Account holders may request a manual credit review by contacting their account manager. Credit limit increases above $100,000 require additional financial documentation including the most recent two years of business tax returns or audited financial statements.', DATE'2026-01-01', CURRENT_TIMESTAMP()),
  (6, 'Food Safety Policy', 'safety', 'Commerce Swarm maintains HACCP-compliant food safety programs across all production facilities. All frozen items ship under continuous-cold-chain monitoring; temperature loggers accompany every B2B foodservice shipment. Customers receiving compromised shipments should refuse delivery or, if discovered post-delivery, report within 24 hours with the temperature logger and photographs. Recalls, when initiated, are communicated to all affected customers within 24 hours via email and posted to the customer portal. We voluntarily disclose all recalls to FDA regardless of severity classification.', DATE'2026-01-01', CURRENT_TIMESTAMP()),
  (7, 'Pricing Policy', 'payment', 'Retail (B2C) prices shown on the website reflect current list prices and are subject to change without notice. Promotional pricing applies only during the published promotional window and to orders placed during that window. B2B contract pricing is established in the account''s service agreement and is honored for the contract term unless commodity costs (dairy, wheat, sugar) exceed agreed thresholds, in which case price adjustments are communicated 30 days in advance. Shipping, handling, and applicable taxes are calculated at checkout and shown on the order summary before payment.', DATE'2026-01-15', CURRENT_TIMESTAMP()),
  (8, 'Damaged & Missing Items Policy', 'returns', 'Customers should inspect shipments upon receipt. Damaged outer cartons should be documented via photograph at the point of delivery if possible. Missing items, broken seals, or thawed-on-arrival frozen products should be reported within 48 hours via the self-service support portal. We will issue a same-day replacement, credit, or refund — customer''s choice — for any verified damaged or missing items. Photographs are required for all claims to enable carrier reimbursement; refusal to provide photographs may limit our ability to credit your account.', DATE'2026-01-01', CURRENT_TIMESTAMP());
